import { forbidden } from 'next/navigation'
import Link from 'next/link'
import { verifyAdmin } from '@/app/lib/auth'

export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin()

  // Throws the auth interrupt caught by `app/forbidden.tsx`, which renders with
  // a real 403 status code instead of a 200 page that merely looks like an error.
  if (!isAdmin) {
    forbidden()
  }

  return (
    <main>
      <h1>Admin Dashboard</h1>
      <p>
        Signed in as <strong>{session!.name}</strong> ({session!.role})
      </p>
      <p>You have full administrative access.</p>
      <Link href="/">Back to home</Link>
    </main>
  )
}

